[  
    DataContractAttribute
  , SysOperationAlwaysInitialize
]
public class METCrossDockSalesOrderAutoExtractTaskContract extends METSysOperationTaskDataContract
{
    guid queueId;
    RefRecId batchJobId;

}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_queueId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _queueId = queueId)
{
    queueId = _queueId;
    return queueId;
}

/// <summary>
/// Gets or sets the batch job ID.
/// </summary>
/// <param name="_batchJobId">The batch job ID to set.</param>
/// <returns>The current batch job ID.</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public RefRecId parmBatchJobId(RefRecId _batchJobId = batchJobId)
{
    batchJobId = _batchJobId;

    return batchJobId;
}
